class Solution:
    def partition(self, s: str) -> List[List[str]]:
        res = []
        def is_palindrome(sub):
            return sub == sub[::-1]
        def solve(start, curr):
            if start == len(s):
                res.append(curr[:])
                return
            for end in range(start, len(s)):
                sub = s[start:end+1]
                if is_palindrome(sub):
                    curr.append(sub)
                    solve(end + 1, curr)
                    curr.pop()
        solve(0, [])
        return res

