class Solution {
    public boolean graphColoring(boolean graph[][], int m, int n) {
        int[] color = new int[n];
        return solve(0, graph, color, m, n);
    }
    private boolean solve(int node, boolean graph[][], int[] color, int m, int n) {
        if (node == n) return true;

        for (int i = 1; i <= m; i++) {
            if (isSafe(node, graph, color, n, i)) {
                color[node] = i;
                if (solve(node + 1, graph, color, m, n)) return true;
                color[node] = 0;
            }
        }
        return false;
    }
    private boolean isSafe(int node, boolean graph[][], int[] color, int n, int col) {
        for (int k = 0; k < n; k++) {
            if (graph[node][k] && color[k] == col) return false;
        }
        return true;
    }
}

