    def isSafe(node, col):
        for i in range(n):
            if graph[node][i] and color[i] == col:
                return False
        return True

    def solve(node):
        if node == n: return True
        for i in range(1, m + 1):
            if isSafe(node, i):
                color[node] = i
                if solve(node + 1): return True
                color[node] = 0
        return False

    return solve(0)

