class Solution:
    def countArrangement(self, n: int) -> int:
        visited = [False] * (n + 1)
        self.count = 0

        def solve(pos):
            if pos > n:
                self.count += 1
                return
            for i in range(1, n + 1):
                if not visited[i] and (i % pos == 0 or pos % i == 0):
                    visited[i] = True
                    solve(pos + 1)
                    visited[i] = False
        solve(1)
        return self.count

